<?php require_once __DIR__ . '/../config/config.php'; require_once __DIR__ . '/../core/AdminAuth.php'; require_once __DIR__ . '/../core/RoomService.php'; $auth = new AdminAuth(); $auth->requireAuth(); $pageTitle = 'Rooms Management'; $roomService = new RoomService(); if (isPost()) { $action = input('action'); if ($action === 'create') { $result = $roomService->create($_POST); if ($result['success']) { setFlash('success', $result['message']); redirect(ADMIN_URL . '/rooms.php'); } $error = $result['error'] ?? 'Failed to create room'; } elseif ($action === 'update') { $result = $roomService->update(input('id'), $_POST); if ($result['success']) { setFlash('success', $result['message']); redirect(ADMIN_URL . '/rooms.php'); } $error = $result['error'] ?? 'Failed to update room'; } elseif ($action === 'delete') { $result = $roomService->delete(input('id')); if ($result['success']) { setFlash('success', $result['message']); } else { setFlash('error', $result['error']); } redirect(ADMIN_URL . '/rooms.php'); } elseif ($action === 'toggle_active') { $id = input('id'); $room = $roomService->getById($id); if ($room['is_active']) { $roomService->deactivate($id); } else { $roomService->activate($id); } redirect(ADMIN_URL . '/rooms.php'); } elseif ($action === 'toggle_lock') { $id = input('id'); $room = $roomService->getById($id); if ($room['is_locked']) { $roomService->unlock($id); } else { $roomService->lock($id); } redirect(ADMIN_URL . '/rooms.php'); } } $rooms = $roomService->getAll(); $editRoom = null; if (input('edit')) { $editRoom = $roomService->getById(input('edit')); } include __DIR__ . '/partials/header.php'; ?> <div class="content-header"> <h2>Rooms Management</h2> <p>Manage conference rooms</p> </div> <div class="card" style="margin-bottom: 20px;"> <div class="card-header">Add/Edit Room</div> <form method="POST"> <input type="hidden" name="action" value="<?php echo $editRoom ? 'update' : 'create'; ?>"> <?php if ($editRoom): ?> <input type="hidden" name="id" value="<?php echo $editRoom['id']; ?>"> <?php endif; ?> <div class="form-group"> <label>Room Name *</label> <input type="text" name="name" class="form-control" value="<?php echo e($editRoom['name'] ?? ''); ?>" required> </div> <div class="form-group"> <label>Description</label> <textarea name="description" class="form-control"><?php echo e($editRoom['description'] ?? ''); ?></textarea> </div> <div class="form-group"> <label>View Mode</label> <select name="view_mode" class="form-control"> <option value="timeline" <?php echo ($editRoom['view_mode'] ?? '') === 'timeline' ? 'selected' : ''; ?>>Timeline</option> <option value="calendar" <?php echo ($editRoom['view_mode'] ?? '') === 'calendar' ? 'selected' : ''; ?>>Calendar</option> <option value="list" <?php echo ($editRoom['view_mode'] ?? '') === 'list' ? 'selected' : ''; ?>>List</option> </select> </div> <div class="form-group"> <label><input type="checkbox" name="is_active" value="1" <?php echo ($editRoom['is_active'] ?? 1) ? 'checked' : ''; ?>> Active</label> </div> <button type="submit" class="btn btn-primary"><?php echo $editRoom ? 'Update' : 'Create'; ?> Room</button> <?php if ($editRoom): ?> <a href="<?php echo ADMIN_URL; ?>/rooms.php" class="btn btn-secondary">Cancel</a> <?php endif; ?> </form> </div> <div class="card"> <div class="card-header">All Rooms</div> <table class="table"> <thead> <tr> <th>ID</th> <th>Name</th> <th>Description</th> <th>View Mode</th> <th>Status</th> <th>Actions</th> </tr> </thead> <tbody> <?php foreach ($rooms as $room): ?> <tr> <td><?php echo $room['id']; ?></td> <td><strong><?php echo e($room['name']); ?></strong></td> <td><?php echo e(substr($room['description'] ?? '', 0, 50)); ?></td> <td><?php echo ucfirst($room['view_mode']); ?></td> <td> <?php if ($room['is_active']): ?> <span style="color: #2ecc71;">● Active</span> <?php else: ?> <span style="color: #e74c3c;">● Inactive</span> <?php endif; ?> <?php if ($room['is_locked']): ?> <span style="color: #f39c12;">🔒 Locked</span> <?php endif; ?> </td> <td> <a href="?edit=<?php echo $room['id']; ?>" class="btn btn-sm btn-primary">Edit</a> <form method="POST" style="display: inline;"> <input type="hidden" name="action" value="toggle_active"> <input type="hidden" name="id" value="<?php echo $room['id']; ?>"> <button type="submit" class="btn btn-sm btn-warning"><?php echo $room['is_active'] ? 'Deactivate' : 'Activate'; ?></button> </form> <form method="POST" style="display: inline;"> <input type="hidden" name="action" value="toggle_lock"> <input type="hidden" name="id" value="<?php echo $room['id']; ?>"> <button type="submit" class="btn btn-sm btn-secondary"><?php echo $room['is_locked'] ? 'Unlock' : 'Lock'; ?></button> </form> <form method="POST" style="display: inline;" onsubmit="return confirm('Delete this room?');"> <input type="hidden" name="action" value="delete"> <input type="hidden" name="id" value="<?php echo $room['id']; ?>"> <button type="submit" class="btn btn-sm btn-danger">Delete</button> </form> </td> </tr> <?php endforeach; ?> </tbody> </table> </div> <?php include __DIR__ . '/partials/footer.php'; ?>
